{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "Ziprasidone, a high-transfer analogue containing an aryl piperazine and halogenated aromatic, has absolute oral bioavailability of 60% in healthy subjects, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "MMV367, a triazole-containing analogue with high transferability, has an estimated human oral bioavailability of 90%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Vilazodone, an aryl piperazine analogue, has absolute oral bioavailability of 72% with food, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Apixaban, a complex heterocyclic drug, has human oral bioavailability of 49%, still well above the 20% threshold, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Delpazolid, an aryl piperazine oxazolidinone, has absolute oral bioavailability of 99.75% in humans, strongly supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Urapidil, an aryl piperazine drug, has absolute oral bioavailability of 72–78%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Ivosidenib, a complex heteroaromatic drug, has absolute oral bioavailability of 57.2% under fasting conditions, directly relevant to the fasted query, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Asciminib, a complex heteroaromatic drug, has absolute oral bioavailability of approximately 73%, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues show oral bioavailability well above 20% (49–100%), with shared piperazine/azole/aryl-halide features; despite unfavorable physicochemical priors, the direct evidence supports high F.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement for the query molecule itself; all evidence is from close analogues.",
    "Some analogue measurements were performed in the fed state, whereas the query condition is fasted; however, fasted data such as ivosidenib support the same direction.",
    "The physicochemical prior suggests solubility/absorption liabilities, but the uniformly high experimental bioavailability of structurally related drugs overrides this prior."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

